package dev.toka.profiles.storage;
import dev.toka.profiles.model.Profile;
import dev.toka.storage.*;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
public final class ProfileRepository implements AutoCloseable {
 public enum State { READY,FAILED,CLOSED }
 private record Index(Map<UUID,Profile> profiles,Map<String,Set<UUID>> names,Map<String,UUID> legacy){}
 private final DocumentStore store;private final ThreadPoolExecutor writer;private volatile Index index;private volatile State state=State.READY;private volatile Throwable failure;
 private ProfileRepository(DocumentStore store,int capacity)throws IOException{this.store=store; if(capacity<1)throw new IllegalArgumentException("Queue capacity");var profiles=new HashMap<UUID,Profile>();try{for(var e:store.snapshot().entrySet()){Profile p=ProfileCodec.decode(e.getValue());if(!e.getKey().equals(ProfileCodec.key(p.uuid()))||profiles.putIfAbsent(p.uuid(),p)!=null)throw new IllegalArgumentException("Conflicting identity/key");}index=build(profiles);}catch(RuntimeException e){throw new IOException("Invalid profile store",e);}writer=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(capacity),r->{var t=new Thread(r,"tokaProfiles-storage");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());}
 public static ProfileRepository open(StoreConfig config,int capacity)throws IOException{DocumentStore store=DocumentStore.open(config);try{return new ProfileRepository(store,capacity);}catch(Throwable e){try{store.close();}catch(IOException close){e.addSuppressed(close);}throw e;}}
 private static String normalize(String n){return n.toLowerCase(Locale.ROOT);}
 private static Index build(Map<UUID,Profile> profiles){var names=new HashMap<String,Set<UUID>>();var legacy=new HashMap<String,UUID>();for(Profile p:profiles.values()){var all=new ArrayList<>(p.aliases());all.add(p.name());for(String name:all){names.computeIfAbsent(normalize(name),ignored->new HashSet<>()).add(p.uuid());}p.legacyId().ifPresent(id->{UUID old=legacy.putIfAbsent(id,p.uuid());if(old!=null&&!old.equals(p.uuid()))throw new IllegalArgumentException("Legacy ID collision: "+id);});}names.replaceAll((key,value)->Set.copyOf(value));return new Index(Map.copyOf(profiles),Map.copyOf(names),Map.copyOf(legacy));}
 public State state(){return state;}public Optional<Throwable> failure(){return Optional.ofNullable(failure);}public Optional<Profile> find(UUID uuid){return Optional.ofNullable(index.profiles().get(uuid));}public Optional<Profile> findByName(String name){var candidates=resolveName(name);return candidates.size()==1?find(candidates.iterator().next()):Optional.empty();}public Set<UUID> resolveName(String name){return index.names().getOrDefault(normalize(Objects.requireNonNull(name)),Set.of());}public Map<UUID,Profile> snapshot(){return index.profiles();}
 public CompletableFuture<Void> put(Profile profile){Objects.requireNonNull(profile);return mutate(profile.uuid(),ignored->profile);}
public CompletableFuture<Void> updateTitle(UUID uuid,String title){Objects.requireNonNull(uuid);Objects.requireNonNull(title);return mutate(uuid,current->{if(current==null)throw new IllegalArgumentException("Profile not found");return current.withTitle(title);});}
private synchronized CompletableFuture<Void> mutate(UUID uuid,java.util.function.UnaryOperator<Profile> change){var result=new CompletableFuture<Void>();if(state!=State.READY){result.completeExceptionally(new IllegalStateException("Store "+state));return result;}try{writer.execute(()->{if(state==State.FAILED){result.completeExceptionally(new IllegalStateException("Storage failed",failure));return;}try{Profile profile=change.apply(index.profiles().get(uuid));var next=new HashMap<>(index.profiles());next.put(profile.uuid(),profile);Index candidate=build(next);store.save(ProfileCodec.key(profile.uuid()),ProfileCodec.encode(profile));index=candidate;result.complete(null);}catch(IllegalArgumentException e){result.completeExceptionally(e);}catch(Throwable e){failure=e;state=State.FAILED;result.completeExceptionally(e);}});}catch(RejectedExecutionException e){result.completeExceptionally(e);}return result;}
 public synchronized void close()throws IOException{if(state==State.CLOSED)return;writer.shutdown();try{if(!writer.awaitTermination(30,TimeUnit.SECONDS))throw new IOException("Writer did not drain; store remains open");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IOException("Interrupted while draining",e);}store.close();state=State.CLOSED;}
}
